        }
      ]
    },
    {
      "id": "craft_spruce_button",
      "description": "Player crafts a spruce button from spruce planks",
      "rules": [
        {
          "type": "inventory_has",
          "params": {
            "item": "spruce_button",
            "quantity_min": 1
          }
        }
      ]
    },
    {
      "id": "light_up_tower",
      "description": "Player lights up the tower by powering the redstone lamps with redstone torches",
